'use client';

import { useEffect, useState, useCallback } from 'react';
import Image from 'next/image';
import {
  FaUserCircle, FaEdit, FaSignOutAlt, FaGraduationCap,
  FaBriefcase, FaChalkboardTeacher, FaUniversity, FaBookmark,
  FaLock, FaUsers, FaEnvelope, FaTimes, FaBars, FaUserFriends
} from 'react-icons/fa';
import { MdEmail, MdSchool, MdInterests, MdPublic } from 'react-icons/md';

export default function ProfilePage() {
  const [user, setUser] = useState({
    firstName: 'Adem',
    lastName: 'Bouafia',
    email: 'adem@example.com',
    university: 'ESSTHS',
    role: 'STUDENT',
    followers: 128,
    following: 64,
    formation: 'Computer Science',
    profilePicture: null
  });
  const [isEditing, setIsEditing] = useState(false);
  const [selectedTab, setSelectedTab] = useState('posts');
  const [showSidebar, setShowSidebar] = useState(false);

  const getRoleIcon = () => {
    switch (user.role) {
      case 'STUDENT': return <MdSchool className="text-blue-500" />;
      default: return <FaUserCircle />;
    }
  };

  const getRoleColor = () => {
    switch (user.role) {
      case 'STUDENT': return 'bg-blue-100 text-blue-800';
      default: return 'bg-gray-100 text-gray-800';
    }
  };

  return (
    <div className="min-h-screen bg-gray-50">
      {/* Sidebar Toggle for Mobile */}
      <button 
        onClick={() => setShowSidebar(true)}
        className="md:hidden fixed top-4 left-4 z-50 p-2 bg-white rounded-md shadow"
      >
        <FaBars className="text-gray-700" />
      </button>

      {/* Main Content */}
      <main className="max-w-4xl mx-auto py-8 px-4">
        {/* Profile Header */}
        <div className="bg-white rounded-xl shadow-md overflow-hidden mb-6">
          <div className="p-6">
            <div className="flex flex-col sm:flex-row items-start sm:items-center gap-6">
              {/* Profile Picture */}
              <div className="relative">
                {user.profilePicture ? (
                  <Image
                    src={user.profilePicture}
                    alt="Profile"
                    width={120}
                    height={120}
                    className="rounded-full object-cover border-4 border-white shadow-md"
                  />
                ) : (
                  <FaUserCircle className="w-[120px] h-[120px] text-gray-300" />
                )}
                <div className="absolute -bottom-2 -right-2 bg-white rounded-full p-1 shadow-md">
                  <span className={`inline-flex items-center px-3 py-1 rounded-full text-xs font-medium ${getRoleColor()}`}>
                    {getRoleIcon()}
                    <span className="ml-1">{user.role.toLowerCase()}</span>
                  </span>
                </div>
              </div>

              {/* User Info */}
              <div className="flex-1">
                <div className="flex justify-between items-start">
                  <div>
                    <h1 className="text-2xl font-bold text-gray-900">
                      {user.firstName} {user.lastName}
                    </h1>
                    <div className="flex items-center mt-1 text-gray-600">
                      <FaUniversity className="mr-2 text-gray-500" />
                      <span>{user.university}</span>
                    </div>
                    
                    {/* Follower/Following Count */}
                    <div className="flex gap-4 mt-3">
                      <div className="flex items-center text-gray-700">
                        <FaUserFriends className="mr-1 text-blue-500" />
                        <span>{user.followers} followers</span>
                      </div>
                      <div className="flex items-center text-gray-700">
                        <span>{user.following} following</span>
                      </div>
                    </div>
                  </div>

                  {/* Action Buttons */}
                  <div className="flex flex-col gap-2">
                    <button
                      onClick={() => setIsEditing(true)}
                      className="flex items-center gap-2 px-3 py-1 bg-blue-600 text-white rounded-md hover:bg-blue-700"
                    >
                      <FaEdit size={14} />
                      <span>Edit</span>
                    </button>
                    <button
                      className="flex items-center gap-2 px-3 py-1 bg-red-600 text-white rounded-md hover:bg-red-700"
                    >
                      <FaSignOutAlt size={14} />
                      <span>Logout</span>
                    </button>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>

        {/* Education Section */}
        <div className="bg-white rounded-xl shadow-md overflow-hidden mb-6">
          <div className="p-6">
            <div className="flex items-center mb-4">
              <MdSchool className="text-blue-500 text-xl mr-2" />
              <h2 className="text-lg font-semibold text-gray-900">Education</h2>
            </div>
            <div className="space-y-3">
              <div>
                <p className="text-sm text-gray-500">Formation</p>
                <p className="font-medium">{user.formation}</p>
              </div>
            </div>
          </div>
        </div>

        {/* Tabs */}
        <div className="bg-white rounded-xl shadow-md overflow-hidden mb-6">
          <nav className="flex border-b border-gray-200">
            <button
              onClick={() => setSelectedTab('posts')}
              className={`px-4 py-3 text-sm font-medium ${selectedTab === 'posts' ? 'text-blue-600 border-b-2 border-blue-600' : 'text-gray-500 hover:text-gray-700'}`}
            >
              Posts
            </button>
            <button
              onClick={() => setSelectedTab('saved')}
              className={`px-4 py-3 text-sm font-medium ${selectedTab === 'saved' ? 'text-blue-600 border-b-2 border-blue-600' : 'text-gray-500 hover:text-gray-700'}`}
            >
              Saved
            </button>
          </nav>

          {/* Tab Content */}
          <div className="p-6">
            {selectedTab === 'posts' ? (
              <div className="text-center py-8">
                <div className="mx-auto w-16 h-16 bg-gray-100 rounded-full flex items-center justify-center mb-4">
                  <FaGraduationCap className="text-gray-400 text-2xl" />
                </div>
                <h3 className="text-lg font-medium text-gray-900 mb-2">No posts yet</h3>
                <p className="text-gray-500">
                  This user hasn't shared any posts yet
                </p>
              </div>
            ) : (
              <div className="text-center py-8">
                <div className="mx-auto w-16 h-16 bg-gray-100 rounded-full flex items-center justify-center mb-4">
                  <FaBookmark className="text-gray-400 text-2xl" />
                </div>
                <h3 className="text-lg font-medium text-gray-900 mb-2">No saved posts</h3>
                <p className="text-gray-500">
                  When you save posts, they'll appear here
                </p>
              </div>
            )}
          </div>
        </div>
      </main>

      {/* Edit Profile Modal */}
      {isEditing && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white rounded-xl p-6 max-w-md w-full">
            <div className="flex justify-between items-center mb-4">
              <h2 className="text-xl font-bold">Edit Profile</h2>
              <button onClick={() => setIsEditing(false)}>
                <FaTimes />
              </button>
            </div>
            {/* Add your form fields here */}
            <div className="mt-4 flex justify-end gap-3">
              <button 
                onClick={() => setIsEditing(false)}
                className="px-4 py-2 border border-gray-300 rounded-md"
              >
                Cancel
              </button>
              <button 
                className="px-4 py-2 bg-blue-600 text-white rounded-md"
              >
                Save
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}